class PartitionFilter
{
public:
	PartitionFilter *link(PartitionFilter *next);

private:
	void *m_vtable;
	PartitionFilter *m_next;
};

PartitionFilter *PartitionFilter::link(PartitionFilter *next)
{
	PartitionFilter *last = m_next;
	if( last != 0 )
	{
		PartitionFilter *cursor = last;
		while( cursor != 0 )
		{
			last = cursor;
			cursor = *reinterpret_cast<PartitionFilter **>(reinterpret_cast<char *>(last) + 4);
		}
		last->m_next = next;
	}
	else
	{
		m_next = next;
	}
	return this;
}
